import { test, expect } from '@playwright/test';

test('settling up clears the balances', async ({ page }) => {
  await page.goto('/groups/lisbon-trip');
  await page.getByLabel('Description').fill('Dinner');
  await page.getByLabel('Amount').fill('30.00');
  await page.getByRole('button', { name: 'Add expense' }).click();
  page.getByRole('button', { name: 'Settle up' }).click();
  await page.waitForTimeout(2000);
  const status = await page.getByRole('status').textContent();
  expect(status).toBe('Everyone is settled up');
  await expect(page.getByRole('listitem')).toHaveCount(0);
});
